WITH metrics AS (SELECT *, LEAD(budget) OVER w_grp AS next_budget, ROW_NUMBER() OVER w_grp AS row_seq FROM departments WHERE dept_name IS NOT NULL WINDOW w_grp AS (PARTITION BY location ORDER BY budget, id)) SELECT location, COUNT(*) FILTER (WHERE dept_name = 'HR') AS hr_rows, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list, COUNT(CASE WHEN location = 'Bangkok' THEN 1 END) AS bangkok_count FROM metrics GROUP BY location ORDER BY bangkok_count NULLS FIRST;
